// ─── AbuseWatch configuration ────────────────────────────────────────────────
// The ONLY place to edit when adding/removing a watched address.
// Add a line to WATCHED and the rest of the workflow picks it up automatically.
//
// REPLACE THESE EXAMPLES with the public addresses you are responsible for.
// (203.0.113.x / 198.51.100.x are the RFC 5737 documentation ranges — they are
// placeholders, not real hosts.)  Watch only addresses you own or administer.
const WATCHED = [
  { ip: '203.0.113.10',  label: 'Home' },
  { ip: '198.51.100.25', label: 'Web server' },
];

const MAX_AGE_DAYS = 90;   // AbuseIPDB report window queried each run (1-365)
const FORCE_POST   = false; // true = post to Slack on every run (manual testing)
// ─────────────────────────────────────────────────────────────────────────────

// A manual run POSTed with ?force=1 posts to Slack even when nothing is new.
// Referencing a trigger that did not fire throws, hence the try/catch.
let forcePost = FORCE_POST;
try {
  forcePost = forcePost || String($('Manual Check').first().json.query.force) === '1';
} catch (e) { /* scheduled run: no Manual Check node output */ }

return WATCHED.map((w) => ({
  json: {
    __kind: 'abusewatch_check',
    ip: String(w.ip).trim(),
    label: w.label,
    maxAgeInDays: MAX_AGE_DAYS,
    forcePost: forcePost,
    checkUrl: 'https://www.abuseipdb.com/check/' + String(w.ip).trim(),
  },
}));

// --- AbuseWatch: diff against stored state, build the Slack post, compute new state ---
// Local timezone used for stamps, the recap hour and the recap's date stamp.
// Keep TZ in sync with the workflow's own timezone setting (Settings -> Timezone).
const TZ               = 'America/New_York';
const TZ_LABEL         = 'ET'; // short label appended to rendered times
const DIGEST_HOUR      = 16; // local hour of the daily "all clean" recap (0-23)
const FAIL_ALERT_AFTER = 3;  // consecutive failed checks before we shout about it
const FAIL_RENAG_EVERY = 24; // ...and how many further failures between reminders
const MAX_BULLETS      = 8;  // report lines rendered per IP in one message

const CATEGORIES = {
  1: 'DNS Compromise', 2: 'DNS Poisoning', 3: 'Fraud Orders', 4: 'DDoS Attack',
  5: 'FTP Brute-Force', 6: 'Ping of Death', 7: 'Phishing', 8: 'Fraud VoIP',
  9: 'Open Proxy', 10: 'Web Spam', 11: 'Email Spam', 12: 'Blog Spam', 13: 'VPN IP',
  14: 'Port Scan', 15: 'Hacking', 16: 'SQL Injection', 17: 'Spoofing',
  18: 'Brute-Force', 19: 'Bad Web Bot', 20: 'Exploited Host', 21: 'Web App Attack',
  22: 'SSH', 23: 'IoT Targeted',
};

// Reporter comments are attacker-influenced free text: escape Slack mrkdwn, flatten, clip.
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const oneLine = (s) => esc(s).replace(/[\s\x00-\x1F]+/g, ' ').trim();
const clip = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

function stamp(d) {
  const t = d instanceof Date ? d : new Date(d);
  if (isNaN(t.getTime())) return '';
  const p = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(t);
  const g = (k) => (p.find((x) => x.type === k) || {}).value;
  return g('year') + '-' + g('month') + '-' + g('day') + ' ' + g('hour') + ':' + g('minute') + ' ' + TZ_LABEL;
}

// n8n reports an HTTP failure as e.g. 401 - "{\"errors\":[{\"detail\":\"...\"}]}" -
// a JSON body nested inside a JSON string. Dig the human sentence back out.
function apiDetail(raw) {
  const msg = String(raw == null ? '' : raw);
  const status = (msg.match(/\b([45]\d\d)\b/) || [])[1];
  const starts = [msg.indexOf('"'), msg.indexOf('{')].filter((i) => i >= 0);
  for (const i of starts) {
    try {
      let v = JSON.parse(msg.slice(i));
      if (typeof v === 'string') v = JSON.parse(v);
      if (v && Array.isArray(v.errors) && v.errors.length) {
        const detail = v.errors.map((e) => e.detail || e.title || JSON.stringify(e)).join('; ');
        return (status ? status + ': ' : '') + detail;
      }
    } catch (e) { /* not this shape; try the next */ }
  }
  return msg;
}

const now = new Date();
const nowStamp = stamp(now);
const localHour = Number(new Intl.DateTimeFormat('en-US', { timeZone: TZ, hour: '2-digit', hourCycle: 'h23' }).format(now));
// en-CA formats as YYYY-MM-DD, which compares correctly as a plain string.
const today = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);

// The Merge feeds us two kinds of item: per-IP check results (tagged by Config)
// and whatever rows the state table currently holds.
const items = $input.all().map((i) => i.json || {});
const checks = items.filter((x) => x.__kind === 'abusewatch_check');
const stateByIp = {};
for (const r of items) {
  if (r.__kind !== 'abusewatch_check' && r.ip) stateByIp[String(r.ip)] = r;
}

const results = [];
for (const c of checks) {
  const prev = stateByIp[c.ip] || null;
  // An empty seen_keys means "never successfully checked" -> treat the next good
  // read as a baseline instead of dumping the whole back catalogue into Slack.
  const isBaseline = !prev || !String(prev.seen_keys || '').trim();
  let prevSeen = new Set();
  try { prevSeen = new Set(JSON.parse(String((prev && prev.seen_keys) || '[]'))); } catch (e) { prevSeen = new Set(); }
  const prevStreak = Number((prev && prev.fail_streak) || 0);

  const d = c.data;
  if (!d || typeof d !== 'object' || d.ipAddress == null) {
    let why = 'unrecognised API response';
    if (c.error) why = apiDetail(typeof c.error === 'string' ? c.error : (c.error.message || JSON.stringify(c.error)));
    else if (Array.isArray(c.errors) && c.errors.length) why = c.errors.map((e) => e.detail || JSON.stringify(e)).join('; ');
    results.push(Object.assign({}, c, { prev, status: 'FAILED', failStreak: prevStreak + 1, error: clip(String(why), 300) }));
    continue;
  }

  const reports = Array.isArray(d.reports) ? d.reports : [];
  const total = Number(d.totalReports || 0);
  const key = (r) => r.reportedAt + '|' + r.reporterId;
  // reports[] only arrives with the verbose flag; fall back to counting if it is missing.
  const detailed = reports.length > 0 || total === 0;
  const newReports = (isBaseline || !detailed) ? [] : reports.filter((r) => !prevSeen.has(key(r)));
  newReports.sort((a, b) => String(b.reportedAt).localeCompare(String(a.reportedAt)));
  const blindNew = (isBaseline || detailed) ? 0 : Math.max(0, total - Number((prev && prev.total_reports) || 0));

  results.push(Object.assign({}, c, {
    prev, status: 'OK', isBaseline, detailed, blindNew, newReports,
    seenKeys: reports.map(key),
    score: Number(d.abuseConfidenceScore || 0),
    total,
    distinct: Number(d.numDistinctUsers || 0),
    lastReportedAt: d.lastReportedAt || '',
    isp: d.isp || '',
    isWhitelisted: d.isWhitelisted === true,
    isTor: d.isTor === true,
    failStreak: 0,
  }));
}

const anyNew = results.some((r) => r.status === 'OK' && (r.newReports.length > 0 || r.blindNew > 0));
const anyBaseline = results.some((r) => r.status === 'OK' && r.isBaseline);
// Shout once when the streak first crosses the threshold, then only daily, so a
// broken API key does not turn into an hourly drumbeat in Slack.
const isFailAlert = (r) => r.status === 'FAILED' && (r.failStreak === FAIL_ALERT_AFTER
  || (r.failStreak > FAIL_ALERT_AFTER && (r.failStreak - FAIL_ALERT_AFTER) % FAIL_RENAG_EVERY === 0));
const anyFailAlert = results.some(isFailAlert);
const anyFailed = results.some((r) => r.status === 'FAILED');
// Latest recap date any row has seen. Missing/blank -> none ever sent.
const lastDigestOn = results
  .map((r) => String((r.prev && r.prev.last_digest_on) || ''))
  .sort()
  .pop() || '';
// Not "it is exactly 16:00" but "it is 16:00 or later and today's recap is still owed",
// so a missed tick (n8n restarting, host down) is caught up on the next run instead of
// being skipped for the day.
const isDigest = localHour >= DIGEST_HOUR && lastDigestOn !== today;
const forcePost = checks.some((c) => c.forcePost === true);

const lines = [];
if (anyNew) lines.push('🚨 *AbuseWatch* — new abuse reports · ' + nowStamp);
else if (anyFailAlert) lines.push('⚠️ *AbuseWatch* — AbuseIPDB checks are failing · ' + nowStamp);
else if (anyBaseline) lines.push('👀 *AbuseWatch* — baseline recorded · ' + nowStamp);
else if (anyFailed) lines.push('⚠️ *AbuseWatch* — no new reports, but some checks did not run · ' + nowStamp);
else lines.push('✅ *AbuseWatch* — all clean · ' + nowStamp);

for (const r of results) {
  lines.push('');
  const who = '*<' + r.checkUrl + '|' + esc(r.label) + '>* `' + esc(r.ip) + '`';

  if (r.status === 'FAILED') {
    const icon = r.failStreak >= FAIL_ALERT_AFTER ? '⚠️' : '⏳';
    lines.push(icon + ' ' + who + ' — check failed (' + r.failStreak + ' run' + (r.failStreak === 1 ? '' : 's') + ' in a row): ' + oneLine(r.error));
    if (r.failStreak >= FAIL_ALERT_AFTER) lines.push('_Check the AbuseIPDB API key credential and the daily quota._');
    continue;
  }

  const head = who + ' — confidence ' + r.score + '%, ' + r.total + ' report' + (r.total === 1 ? '' : 's') + ' in ' + r.maxAgeInDays + 'd';

  if (r.isBaseline) {
    lines.push(head + ' — _baseline recorded; new reports from here on will be flagged_');
  } else if (r.newReports.length) {
    lines.push(head + ' · *' + r.newReports.length + ' new*');
    for (const rep of r.newReports.slice(0, MAX_BULLETS)) {
      const cats = (rep.categories || []).map((n) => CATEGORIES[n] || ('category ' + n)).join(', ') || 'uncategorised';
      const from = rep.reporterCountryCode ? ' [' + esc(rep.reporterCountryCode) + ']' : '';
      lines.push('• `' + stamp(rep.reportedAt) + '` ' + esc(cats) + from + ' — _' + clip(oneLine(rep.comment || '(no comment)'), 160) + '_');
    }
    if (r.newReports.length > MAX_BULLETS) lines.push('• _…and ' + (r.newReports.length - MAX_BULLETS) + ' more_');
  } else if (r.blindNew > 0) {
    lines.push(head + ' · *' + r.blindNew + ' new* — _report detail unavailable; open the link for the list_');
  } else {
    const last = r.lastReportedAt ? ', last ' + stamp(r.lastReportedAt) : '';
    lines.push(head + last + ' — no new reports');
  }
  if (r.isWhitelisted) lines.push('_AbuseIPDB has this address whitelisted._');
  if (r.isTor) lines.push('_AbuseIPDB flags this address as a Tor exit node._');
}

const digestClock = (DIGEST_HOUR % 12 || 12) + (DIGEST_HOUR < 12 ? 'am' : 'pm') + ' ' + TZ_LABEL;
if (!anyNew && !anyFailAlert && !anyFailed) lines.push('', '_Checked hourly; this recap posts once a day, from ' + digestClock + '._');

const nowIso = now.toISOString();
const states = results.map((r) => ({
  ip: r.ip,
  label: r.label,
  last_check_at: nowIso,
  // A failed check must never clobber the state a good check left behind.
  last_reported_at: r.status === 'OK' ? String(r.lastReportedAt || '') : String((r.prev && r.prev.last_reported_at) || ''),
  total_reports: r.status === 'OK' ? r.total : Number((r.prev && r.prev.total_reports) || 0),
  abuse_score: r.status === 'OK' ? r.score : Number((r.prev && r.prev.abuse_score) || 0),
  seen_keys: r.status === 'OK' ? JSON.stringify(r.seenKeys) : String((r.prev && r.prev.seen_keys) || ''),
  fail_streak: r.failStreak,
  last_error: r.status === 'FAILED' ? r.error : '',
  // isDigest implies we are posting, so mark the day done; otherwise carry forward.
  last_digest_on: isDigest ? today : lastDigestOn,
}));

return [{
  json: {
    shouldPost: forcePost || anyNew || anyBaseline || anyFailAlert || isDigest,
    text: lines.join('\n'),
    anyNew: anyNew,
    anyBaseline: anyBaseline,
    anyFailAlert: anyFailAlert,
    isDigest: isDigest,
    localHour: localHour,
    states: states,
  },
}];

// Returning zero items stops the branch, so quiet runs post nothing at all.
const j = $input.first().json;
return j.shouldPost ? [{ json: { text: j.text } }] : [];
